<?php
namespace App;
class Cart
{
    private array $items = [];
    public function addItem(int $itemId, int $qty, int $price, int $discount = 0): void
    {
        $this->items[] = ['item_id' => $itemId, 'qty' => $qty, 'price' => $price, 'discount' => $discount];
    }
    public function items(): array { return $this->items; }
    public function total(): int
    {
        $sum = 0;
        foreach ($this->items as $item) { $sum += $item['qty'] * $item['price'] - $item['discount']; }
        return $sum;
    }
}

```

#### `app/Http/CartController.php`
```
<?php
namespace App\Http;
use App\Cart;
class CartController
{
    public function __construct(private Cart $cart) {}
    public function store(array $request): array
    {
        $discount = (int) ($request['discount_amount'] ?? 0);
        if ($discount > (int) config('cart.max_item_discount')) {
            throw new \InvalidArgumentException('diskon melebihi batas');
        }
        $this->cart->addItem($request['item_id'], (int) $request['qty'], (int) $request['price'], $discount);
        return ['total' => $this->cart->total()];
    }
}

```

